print('TOP description:', s.get('description'))
def find(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items():
            if k=='programBindings' and isinstance(v,dict): print('programBindings @',path,':',v.get('description'))
            find(v,path+'/'+k)
    elif isinstance(o,list):
        for i,v in enumerate(o): find(v,path+'/'+str(i))
find(s)
n=json.loads((R/'native/native-evidence.schemas.v2.json').read_text())
