print('TSCG description:', t.get('description'))
print('entryConfigPath:', json.dumps(t['properties']['entryConfigPath']))
for k,v in n['\$defs'].items():
    txt=json.dumps(v)
    if 'programEntry' in txt or 'U-1' in txt: print('native def mentions:', k, [m for m in ('programEntry','U-1') if m in txt])
"

